/* Auto-generated: approved neon orb loop for bubbles dashboard. Do not edit by hand. */
(function(){
  var b64="";
  var bin=atob(b64);
  var arr=new Uint8Array(bin.length);
  for(var i=0;i<bin.length;i++) arr[i]=bin.charCodeAt(i);
  var url=URL.createObjectURL(new Blob([arr],{type:"video/mp4"}));
  function apply(){
    document.querySelectorAll("video.orb-vid").forEach(function(v){
      if(v.dataset.orbSrcApplied) return;
      v.dataset.orbSrcApplied="1";
      v.src=url;
      v.muted=true;
      var p=v.play();
      if(p&&p.catch) p.catch(function(){});
    });
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",apply);
  else apply();
  // also when gate unlocks / app shown
  var obs=new MutationObserver(apply);
  if(document.documentElement) obs.observe(document.documentElement,{childList:true,subtree:true,attributes:true});
})();
